// queue is refilled by incoming events faster than items are removed
function drain() {
  if (queue.length === 0) return;
  const item = queue.shift();
  process(item);
  // BUG: re-schedules as a microtask -> never yields to render/input
  Promise.resolve().then(drain);
}
